//go:build ignore

package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

type declKey struct {
	pkgPath  string
	name     string
	recvType string
	isMethod bool
}

type declInfo struct {
	key    declKey
	file   string
	line   int
	isTest bool
	isGen  bool
}

type callRecord struct {
	callerPkg  string
	callerName string
	callerRecv string
	callerFile string
	callerLine int
	callerTest bool
}

type fanInStats struct {
	info             declInfo
	callSites        int
	distinctCallers  map[string]callRecord
	distinctFiles    map[string]int
	nonTestCallSites int
	nonTestCallers   map[string]callRecord
}

func main() {
	repoRoot := "/bench/repo"
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax |
			packages.NeedTypes | packages.NeedTypesInfo | packages.NeedImports |
			packages.NeedModule,
		Dir:   repoRoot,
		Tests: true,
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	for _, p := range pkgs {
		for _, e := range p.Errors {
			fmt.Fprintf(os.Stderr, "pkg %s: %v\n", p.PkgPath, e)
		}
	}

	decls := map[declKey]*declInfo{}
	calleeToCalls := map[declKey][]callRecord{}

	for _, pkg := range pkgs {
		if pkg.Types == nil || pkg.Fset == nil || pkg.TypesInfo == nil {
			continue
		}

		for _, f := range pkg.Syntax {
			if f == nil {
				continue
			}
			ast.Inspect(f, func(n ast.Node) bool {
				fd, ok := n.(*ast.FuncDecl)
				if !ok || fd.Name == nil {
					return true
				}
				pos := pkg.Fset.Position(fd.Name.Pos())
				fp := relPath(repoRoot, pos.Filename)
				if !strings.HasPrefix(fp, "internal/") {
					return true
				}
				key := declKey{pkgPath: pkg.PkgPath, name: fd.Name.Name}
				if fd.Recv != nil && len(fd.Recv.List) > 0 {
					key.isMethod = true
					key.recvType = recvTypeString(fd.Recv.List[0].Type)
				}
				if _, ok := decls[key]; !ok {
					decls[key] = &declInfo{
						key:    key,
						file:   fp,
						line:   pos.Line,
						isTest: strings.HasSuffix(fp, "_test.go"),
						isGen:  isGenerated(fp),
					}
				}
				return true
			})
		}

		for _, f := range pkg.Syntax {
			if f == nil {
				continue
			}
			var currentFunc *ast.FuncDecl
			ast.Inspect(f, func(n ast.Node) bool {
				switch node := n.(type) {
				case *ast.FuncDecl:
					currentFunc = node
				case *ast.CallExpr:
					callee := resolveCallee(pkg, node, decls)
					if callee == nil {
						return true
					}
					caller := callerIdentity(pkg, currentFunc, f, pkg.Fset, repoRoot)
					calleeToCalls[callee.key] = append(calleeToCalls[callee.key], caller)
				}
				return true
			})
		}
	}

	stats := make([]*fanInStats, 0, len(decls))
	for key, info := range decls {
		calls := calleeToCalls[key]
		fs := &fanInStats{
			info:            *info,
			distinctCallers: map[string]callRecord{},
			distinctFiles:   map[string]int{},
			nonTestCallers:  map[string]callRecord{},
		}
		for _, c := range calls {
			fs.callSites++
			id := callerID(c)
			fs.distinctCallers[id] = c
			fs.distinctFiles[c.callerFile]++
			if !c.callerTest {
				fs.nonTestCallSites++
				fs.nonTestCallers[id] = c
			}
		}
		stats = append(stats, fs)
	}

	fmt.Println("=== METRIC: type-resolved static call graph fan-in ===")
	fmt.Printf("Total internal declarations scanned: %d\n\n", len(decls))

	sortByNonTest(stats)
	fmt.Println("=== TOP 40 by non-test call-site count ===")
	for i, s := range stats {
		if i >= 40 || s.nonTestCallSites == 0 {
			break
		}
		printStat(s)
	}

	sortByTotal(stats)
	fmt.Println("\n=== TOP 40 by total call-site count ===")
	for i, s := range stats {
		if i >= 40 || s.callSites == 0 {
			break
		}
		printStat(s)
	}

	sortByDistinctNonTestCallers(stats)
	fmt.Println("\n=== TOP 40 by distinct non-test caller functions ===")
	for i, s := range stats {
		if i >= 40 || len(s.nonTestCallers) == 0 {
			break
		}
		printStatDistinct(s)
	}

	fmt.Println("\n=== AMBIGUITY: duplicate simple names in internal/ (with fan-in) ===")
	nameCounts := map[string][]*fanInStats{}
	for _, s := range stats {
		if s.nonTestCallSites > 0 {
			nameCounts[s.info.key.name] = append(nameCounts[s.info.key.name], s)
		}
	}
	type amb struct {
		name string
		n    int
	}
	var ambs []amb
	for n, ss := range nameCounts {
		if len(ss) > 1 {
			ambs = append(ambs, amb{n, len(ss)})
		}
	}
	sort.Slice(ambs, func(i, j int) bool { return ambs[i].n > ambs[j].n })
	for _, a := range ambs[:min(20, len(ambs))] {
		fmt.Printf("name=%q variants=%d\n", a.name, a.n)
		for _, s := range nameCounts[a.name] {
			fmt.Printf("  %s @ %s:%d non_test_sites=%d\n", formatSym(s.info.key), s.info.file, s.info.line, s.nonTestCallSites)
		}
	}

	sortByNonTest(stats)
	if len(stats) > 0 && stats[0].nonTestCallSites > 0 {
		w := stats[0]
		fmt.Println("\n=== WINNER (non-test call-site fan-in) ===")
		fmt.Printf("symbol: %s\n", formatSym(w.info.key))
		fmt.Printf("declaration: %s:%d\n", w.info.file, w.info.line)
		fmt.Printf("non_test_call_sites: %d\n", w.nonTestCallSites)
		fmt.Printf("distinct_non_test_callers: %d\n", len(w.nonTestCallers))
		fmt.Printf("distinct_non_test_caller_files: %d\n", countNonTestFiles(w))
		fmt.Printf("total_call_sites_incl_tests: %d\n", w.callSites)
		fmt.Printf("distinct_total_callers: %d\n", len(w.distinctCallers))
		fmt.Println("\nCaller sample (non-test):")
		printCallerSample(w, 20)
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func countNonTestFiles(w *fanInStats) int {
	m := map[string]bool{}
	for _, c := range w.nonTestCallers {
		m[c.callerFile] = true
	}
	return len(m)
}

func printCallerSample(w *fanInStats, n int) {
	type kv struct {
		id string
		c  callRecord
	}
	var items []kv
	for id, c := range w.nonTestCallers {
		items = append(items, kv{id, c})
	}
	sort.Slice(items, func(i, j int) bool { return items[i].c.callerFile < items[j].c.callerFile })
	for i, it := range items {
		if i >= n {
			break
		}
		sym := it.c.callerName
		if it.c.callerRecv != "" {
			sym = fmt.Sprintf("(%s).%s", it.c.callerRecv, it.c.callerName)
		}
		fmt.Printf("  %s @ %s\n", sym, it.c.callerFile)
	}
}

func sortByNonTest(stats []*fanInStats) {
	sort.Slice(stats, func(i, j int) bool {
		if stats[i].nonTestCallSites != stats[j].nonTestCallSites {
			return stats[i].nonTestCallSites > stats[j].nonTestCallSites
		}
		if len(stats[i].nonTestCallers) != len(stats[j].nonTestCallers) {
			return len(stats[i].nonTestCallers) > len(stats[j].nonTestCallers)
		}
		return stats[i].info.key.name < stats[j].info.key.name
	})
}

func sortByTotal(stats []*fanInStats) {
	sort.Slice(stats, func(i, j int) bool {
		if stats[i].callSites != stats[j].callSites {
			return stats[i].callSites > stats[j].callSites
		}
		return stats[i].info.key.name < stats[j].info.key.name
	})
}

func sortByDistinctNonTestCallers(stats []*fanInStats) {
	sort.Slice(stats, func(i, j int) bool {
		if len(stats[i].nonTestCallers) != len(stats[j].nonTestCallers) {
			return len(stats[i].nonTestCallers) > len(stats[j].nonTestCallers)
		}
		return stats[i].nonTestCallSites > stats[j].nonTestCallSites
	})
}

func printStat(s *fanInStats) {
	fmt.Printf("%s | %s:%d | sites=%d callers=%d files=%d | non_test_sites=%d non_test_callers=%d\n",
		formatSym(s.info.key), s.info.file, s.info.line,
		s.callSites, len(s.distinctCallers), len(s.distinctFiles),
		s.nonTestCallSites, len(s.nonTestCallers))
}

func printStatDistinct(s *fanInStats) {
	fmt.Printf("%s | %s:%d | non_test_callers=%d non_test_sites=%d | total_sites=%d\n",
		formatSym(s.info.key), s.info.file, s.info.line,
		len(s.nonTestCallers), s.nonTestCallSites, s.callSites)
}

func formatSym(k declKey) string {
	if k.isMethod {
		return fmt.Sprintf("(%s).%s", k.recvType, k.name)
	}
	return k.name
}

func resolveCallee(pkg *packages.Package, call *ast.CallExpr, decls map[declKey]*declInfo) *declInfo {
	ti := pkg.TypesInfo
	if ti == nil {
		return nil
	}
	var obj types.Object
	switch fun := call.Fun.(type) {
	case *ast.SelectorExpr:
		if sel := ti.Selections[fun]; sel != nil {
			obj = sel.Obj()
		} else {
			obj = ti.ObjectOf(fun.Sel)
		}
	case *ast.Ident:
		obj = ti.ObjectOf(fun)
	}
	if obj == nil || obj.Pkg() == nil {
		return nil
	}
	pkgPath := obj.Pkg().Path()
	if !strings.HasPrefix(pkgPath, "github.com/usememos/memos/internal") {
		return nil
	}
	key := declKey{pkgPath: pkgPath, name: obj.Name()}
	if fn, ok := obj.(*types.Func); ok {
		if sig := fn.Type().(*types.Signature); sig != nil && sig.Recv() != nil {
			key.isMethod = true
			key.recvType = types.TypeString(sig.Recv().Type(), func(*types.Package) string { return "" })
			key.recvType = strings.TrimPrefix(key.recvType, "*")
		}
	}
	if d, ok := decls[key]; ok {
		return d
	}
	return nil
}

func callerIdentity(pkg *packages.Package, fd *ast.FuncDecl, f *ast.File, fset *token.FileSet, repoRoot string) callRecord {
	rec := callRecord{callerPkg: pkg.PkgPath}
	if fd != nil && fd.Name != nil {
		rec.callerName = fd.Name.Name
		if fd.Recv != nil && len(fd.Recv.List) > 0 {
			rec.callerRecv = recvTypeString(fd.Recv.List[0].Type)
		}
		pos := fset.Position(fd.Name.Pos())
		rec.callerFile = relPath(repoRoot, pos.Filename)
		rec.callerLine = pos.Line
	} else {
		pos := fset.Position(f.Pos())
		rec.callerFile = relPath(repoRoot, pos.Filename)
		rec.callerName = "<init>"
	}
	rec.callerTest = strings.HasSuffix(rec.callerFile, "_test.go")
	return rec
}

func callerID(c callRecord) string {
	return fmt.Sprintf("%s|%s|%s|%s", c.callerPkg, c.callerRecv, c.callerName, c.callerFile)
}

func recvTypeString(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		if id, ok := t.X.(*ast.Ident); ok {
			return id.Name
		}
		return types.ExprString(t)
	case *ast.SelectorExpr:
		return types.ExprString(t)
	default:
		return types.ExprString(expr)
	}
}

func relPath(root, abs string) string {
	if rel, err := filepath.Rel(root, abs); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(abs)
}

func isGenerated(path string) bool {
	return strings.Contains(path, ".pb.go") || strings.Contains(path, "mock_")
}
