#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = '/bench/repo';
my $MOD = 'github.com/usememos/memos';

# decl_key -> { file, line, sym, pkgpath, name, recv, is_test, is_gen }
my %decls;
# decl_key -> [ { caller_key, caller_file, caller_test, line } ]
my %calls;

my @all_go;

find(sub {
    return unless /\.go$/;
    push @all_go, $File::Find::name;
}, $ROOT);

sub rel($) {
    my ($p) = @_;
    $p =~ s/^\Q$ROOT\E\/?//;
    return $p;
}

sub is_test_file($) {
    my ($f) = @_;
    return $f =~ /_test\.go$/;
}

sub is_gen_file($) {
    my ($f) = @_;
    return $f =~ /\.pb\.go$/ || $f =~ /mock_/;
}

sub strip_go_source($) {
    my ($s) = @_;
    # remove raw strings
    $s =~ s/`(?:\\.|[^`\\])*`//gs;
    # remove double-quoted strings
    $s =~ s/"(?:\\.|[^"\\])*"//gs;
    # remove single-quoted runes
    $s =~ s/'(?:\\.|[^'\\])*'//gs;
    # remove line comments
    $s =~ s{//.*$}{}gm;
    # remove block comments
    $s =~ s{/\*.*?\*/}{}gs;
    return $s;
}

sub pkgpath_from_file($) {
    my ($file) = @_;
    my $rel = rel($file);
    return undef unless $rel =~ /^internal\//;
    my $dir = dirname($rel);
    $dir =~ s{/}{.}g if $dir ne '.';
    return "$MOD/internal" if $dir eq 'internal' || $dir eq '.';
    return "$MOD/$dir";
}

sub parse_file($) {
    my ($file) = @_;
    open my $fh, '<', $file or return undef;
    local $/;
    my $src = <$fh>;
    close $fh;
    my $clean = strip_go_source($src);
    my $rel = rel($file);

    my ($pkg) = $clean =~ /^package\s+(\w+)/m;
    return undef unless defined $pkg;

    my %imports; # local_name -> import_path
    my $multi;
    while ($clean =~ /\bimport\s+(?:\(\s*(.*?)\s*\)|"([^"]+)"|(\w+)\s+"([^"]+)")/gs) {
        if (defined $2) {
            my $path = $2;
            (my $local = $path) =~ s/.*\///;
            $imports{$local} = $path;
        } elsif (defined $3) {
            $imports{$3} = $4;
        } elsif (defined $1) {
            my $block = $1;
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                $alias //= ($path =~ s/.*\///r);
                $imports{$alias} = $path;
            }
        }
    }

    my @funcs; # func decls in this file for caller identity
    my $pkgpath = pkgpath_from_file($file);
    # For non-internal files, pkgpath is undef but we still need package for same-package resolution
    my $full_pkgpath = "$MOD/" . rel($file);
    $full_pkgpath =~ s{/[^/]+$}{};

    # Extract function declarations
    while ($clean =~ /^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/gm) {
        my ($recv, $name) = ($1, $2);
        my $pos = pos($clean);
        my $line = 1 + ($clean =~ tr/\n//c); # wrong - need line from pos
        # compute line properly
        my $prefix = substr($clean, 0, $pos);
        my $line_num = ($prefix =~ tr/\n//) + 1;

        my $recv_type = '';
        if (defined $recv && $recv ne '') {
            if ($recv =~ /\*\s*([\w\.]+)/) { $recv_type = $1; }
            elsif ($recv =~ /([\w\.]+)\s*$/) { $recv_type = $1; }
            $recv_type =~ s/^.*\.//;
        }

        push @funcs, { name => $name, recv => $recv_type, line => $line_num };

        if ($pkgpath && $rel =~ /^internal\//) {
            my $key = decl_key($pkgpath, $name, $recv_type);
            unless (exists $decls{$key}) {
                my $sym = $recv_type ? "($recv_type).$name" : $name;
                $decls{$key} = {
                    key => $key, file => $rel, line => $line_num, sym => $sym,
                    pkgpath => $pkgpath, name => $name, recv => $recv_type,
                    is_test => is_test_file($rel), is_gen => is_gen_file($rel),
                };
            }
        }
    }

    return {
        file => $rel,
        pkg => $pkg,
        pkgpath => $full_pkgpath,
        imports => \%imports,
        is_test => is_test_file($rel),
        clean => $clean,
        src => $src,
    };
}

sub decl_key($$$) {
    my ($pkgpath, $name, $recv) = @_;
    $recv //= '';
    return "$pkgpath|$recv|$name";
}

# Pass 1: collect declarations
my %files;
for my $f (@all_go) {
    my $info = parse_file($f);
    $files{rel($f)} = $info if $info;
}

# Build per-package function sets for internal packages
my %pkg_funcs;    # pkgpath -> { name -> 1 }
my %pkg_methods;  # pkgpath -> { recv|name -> 1 }
my %method_by_name; # name -> [ keys ]
for my $d (values %decls) {
    if ($d->{recv}) {
        $pkg_methods{$d->{pkgpath}}{"$d->{recv}|$d->{name}"} = 1;
        push @{ $method_by_name{$d->{name}} }, $d->{key};
    } else {
        $pkg_funcs{$d->{pkgpath}}{$d->{name}} = 1;
    }
}

sub resolve_func_call($$$) {
    my ($info, $pkg_alias, $func_name) = @_;
    my $imports = $info->{imports};

    if (defined $pkg_alias) {
        my $path = $imports->{$pkg_alias};
        return undef unless defined $path;
        return undef unless $path =~ m{^\Q$MOD/internal\E(/|$)};
        my $key = decl_key($path, $func_name, '');
        return $key if exists $decls{$key};
        return undef;
    }

    # same-package call
    my $file = $info->{file};
    if ($file =~ /^internal\//) {
        my $pp = pkgpath_from_file("$ROOT/$file");
        my $key = decl_key($pp, $func_name, '');
        return $key if exists $decls{$key};
    }
    # also check if current file's package path matches an internal decl via directory
    my $pp = $info->{pkgpath};
    if ($pp =~ m{^\Q$MOD/internal\E(/|$)}) {
        my $key = decl_key($pp, $func_name, '');
        return $key if exists $decls{$key};
    }
    return undef;
}

sub infer_var_types($) {
    my ($body) = @_;
    my %types;
    while ($body =~ /\b(\w+)\s*:?=\s*(?:&|\*)?([\w\.]+)\{/g) {
        my ($v, $t) = ($1, $2);
        $t =~ s/^.*\.//;
        $types{$v} = $t;
    }
    while ($body =~ /\b(\w+)\s*:?=\s*(?:&|\*)?([\w\.]+)\(/g) {
        my ($v, $t) = ($1, $2);
        next if $t =~ /^(make|new|append|len|cap|delete|close|panic|recover|print|println)$/;
        $t =~ s/^.*\.//;
        $types{$v} = $t;
    }
    while ($body =~ /(?:var|,\s*)\s*(\w+)\s+(?:\*([\w\.]+)|([\w\.]+))/g) {
        my ($v, $tp, $t) = ($1, $2, $3);
        $t //= $tp;
        $t =~ s/^.*\.//;
        $types{$v} = $t;
    }
    return \%types;
}

sub resolve_method_call($$$$) {
    my ($info, $recv_expr, $method_name) = @_;
    my $imports = $info->{imports};

    # explicit type method: Type.Method or (*Type).Method in call? rare in calls
    if ($recv_expr =~ /^([\w\.]+)$/) {
        my $t = $1;
        $t =~ s/^.*\.//;
        # could be package alias
        if (exists $imports->{$t}) {
            my $path = $imports->{$t};
            if ($path =~ m{^\Q$MOD/internal\E(/|$)}) {
                my $key = decl_key($path, $method_name, $t);
                # method on type named like package - uncommon
            }
            return undef;
        }
    }

    # find enclosing function body for type inference
    return (undef, 'ambiguous');
}

sub record_call($$$$) {
    my ($decl_key, $info, $caller_name, $caller_recv) = @_;
    return unless defined $decl_key && exists $decls{$decl_key};
    my $caller_sym = $caller_recv ? "($caller_recv).$caller_name" : $caller_name;
    my $caller_id = "$info->{pkgpath}|$caller_recv|$caller_name|$info->{file}";
    push @{ $calls{$decl_key} }, {
        caller_id => $caller_id,
        caller_file => $info->{file},
        caller_test => $info->{is_test},
        caller_sym => $caller_sym,
    };
}

# Pass 2: find call sites per function body
for my $f (@all_go) {
    my $rel = rel($f);
    my $info = $files{$rel} or next;
    my $clean = $info->{clean};

    # split by func declarations
    while ($clean =~ /^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\([^)]*\)\s*(?:\([^)]*\)\s*)?\{/gm) {
        my ($recv_raw, $fname) = ($1, $2);
        my $start = pos($clean);
        my $recv = '';
        if (defined $recv_raw && $recv_raw ne '') {
            if ($recv_raw =~ /\*\s*([\w\.]+)/) { $recv = $1; }
            elsif ($recv_raw =~ /([\w\.]+)\s*$/) { $recv = $1; }
            $recv =~ s/^.*\.//;
        }

        # extract balanced body - simplified: until next top-level func or EOF
        my $rest = substr($clean, $start);
        my $depth = 1;
        my $i = 0;
        my $len = length($rest);
        while ($i < $len && $depth > 0) {
            my $c = substr($rest, $i, 1);
            if ($c eq '{') { $depth++; }
            elsif ($c eq '}') { $depth--; }
            $i++;
        }
        my $body = substr($rest, 0, $i);
        pos($clean) = $start + $i;

        my $var_types = infer_var_types($body);

        # package.func calls
        while ($body =~ /\b([\w\.]+)\.(\w+)\s*\(/g) {
            my ($lhs, $fn) = ($1, $2);
            next if $fn =~ /^(Bool|String|Int|Int64|Float64|Error|Bytes|Duration|Interface|Uint64)$/;
            my $key;
            if ($lhs =~ /^[\w]+$/) {
                $key = resolve_func_call($info, $lhs, $fn);
            }
            if ($key) {
                record_call($key, $info, $fname, $recv);
                next;
            }
            # method call: lhs is variable
            my $rtype = $var_types->{$lhs};
            if (!$rtype && $lhs =~ /^[\w]+$/) {
                # try all internal packages imported + same package
                my @candidates;
                for my $pp (keys %pkg_methods) {
                    for my $rk (keys %{ $pkg_methods{$pp} }) {
                        my ($rt, $mn) = split /\|/, $rk, 2;
                        push @candidates, decl_key($pp, $mn, $rt) if $mn eq $fn;
                    }
                }
                @candidates = grep { exists $decls{$_} } @candidates;
                if (@candidates == 1) {
                    record_call($candidates[0], $info, $fname, $recv);
                } elsif ($rtype) {
                    for my $pp (keys %pkg_methods) {
                        my $k = decl_key($pp, $fn, $rtype);
                        if (exists $decls{$k}) {
                            record_call($k, $info, $fname, $recv);
                            last;
                        }
                    }
                }
            } elsif ($rtype) {
                for my $pp (keys %pkg_methods) {
                    my $k = decl_key($pp, $fn, $rtype);
                    if (exists $decls{$k}) {
                        record_call($k, $info, $fname, $recv);
                        last;
                    }
                }
            }
        }

        # bare func calls (same package)
        while ($body =~ /(?:^|[^\w\.])([\w]+)\s*\(/gm) {
            my ($fn) = ($1);
            next if $fn =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|panic|recover|print|println)$/;
            my $key = resolve_func_call($info, undef, $fn);
            record_call($key, $info, $fname, $recv) if $key;
        }
    }

    # init and top-level calls in internal files
    if ($rel =~ /^internal\//) {
        while ($clean =~ /\b([\w\.]+)\.(\w+)\s*\(/g) {
            my ($lhs, $fn) = ($1, $2);
            my $key = resolve_func_call($info, ($lhs =~ /^(\w+)$/ ? $1 : undef), $fn);
            # only if lhs is single ident (import alias)
            if ($lhs =~ /^(\w+)$/) {
                $key = resolve_func_call($info, $1, $fn);
                record_call($key, $info, '<toplevel>', '') if $key;
            }
        }
    }
}

# Aggregate stats
my @stats;
for my $key (keys %decls) {
    my $d = $decls{$key};
    my @c = @{ $calls{$key} // [] };
    my (%callers, %files, %nt_callers, %nt_files);
    my ($sites, $nt_sites) = (scalar @c, 0);
    for my $c (@c) {
        $callers{ $c->{caller_id} } = 1;
        $files{ $c->{caller_file} }++;
        unless ($c->{caller_test}) {
            $nt_sites++;
            $nt_callers{ $c->{caller_id} } = 1;
            $nt_files{ $c->{caller_file} } = 1;
        }
    }
    push @stats, {
        d => $d,
        sites => $sites,
        callers => scalar keys %callers,
        files => scalar keys %files,
        nt_sites => $nt_sites,
        nt_callers => scalar keys %nt_callers,
        nt_files => scalar keys %nt_files,
    };
}

@stats = sort { $b->{nt_sites} <=> $a->{nt_sites} || $b->{nt_callers} <=> $a->{nt_callers} } @stats;

print "=== Perl static fan-in (import + same-package + local type inference) ===\n";
print "Internal declarations: ", scalar keys %decls, "\n\n";

print "TOP 40 by non-test call sites:\n";
for my $i (0..39) {
    last unless $i < @stats && $stats[$i]{nt_sites} > 0;
    my $s = $stats[$i];
    printf "%s | %s:%d | sites=%d callers=%d files=%d | nt_sites=%d nt_callers=%d nt_files=%d\n",
        $s->{d}{sym}, $s->{d}{file}, $s->{d}{line},
        $s->{sites}, $s->{callers}, $s->{files},
        $s->{nt_sites}, $s->{nt_callers}, $s->{nt_files};
}

if (@stats && $stats[0]{nt_sites} > 0) {
    my $w = $stats[0]{d};
    print "\nWINNER: $w->{sym} @ $w->{file}:$w->{line} nt_sites=$stats[0]{nt_sites} nt_callers=$stats[0]{nt_callers}\n";
}
PERLEOF
