#!/usr/bin/perl
use strict;
use warnings;

my $ROOT = '/bench/repo';
my $MOD = 'github.com/usememos/memos';

my %decls;
my %calls;

my @all_go = split /\n/, `find '$ROOT' -name '*.go' 2>/dev/null`;

sub rel($) {
    my ($p) = @_;
    $p =~ s/^\Q$ROOT\E\/?//;
    return $p;
}

sub is_test_file($) { $_[0] =~ /_test\.go$/ }
sub is_gen_file($) { $_[0] =~ /\.pb\.go$/ || $_[0] =~ /mock_/ }

sub strip_go_source($) {
    my ($s) = @_;
    $s =~ s/`(?:\\.|[^`\\])*`//gs;
    $s =~ s/"(?:\\.|[^"\\])*"//gs;
    $s =~ s/'(?:\\.|[^'\\])*'//gs;
    $s =~ s{//.*$}{}gm;
    $s =~ s{/\*.*?\*/}{}gs;
    return $s;
}

sub pkgpath_from_rel($) {
    my ($rel) = @_;
    return undef unless $rel =~ /^internal\//;
    my $dir = $rel;
    $dir =~ s{/[^/]+$}{};
    $dir =~ s{/}{.}g;
