            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                $alias //= ($path =~ s/.*\///r);
                $imports{$alias} = $path;
            }
        }
    }

    my $pkgpath = pkgpath_from_rel($rel);
