        my $key = decl_key($path, $func_name, '');
        return $key if exists $decls{$key};
        return undef;
    }
    my $pp = pkgpath_from_rel($info->{file});
    if ($pp) {
        my $key = decl_key($pp, $func_name, '');
        return $key if exists $decls{$key};
