        $t =~ s/^.*\.//; $types{$v} = $t;
    }
    while ($body =~ /(?:^|[,\s])(\w+)\s+(?:\*([\w\.]+)|([\w\.]+))/gm) {
        my ($v, $tp, $t) = ($1, $2, $3); $t //= $tp; $t =~ s/^.*\.//; $types{$v} = $t;
    }
    return \%types;
}

sub resolve_method($$$$) {
    my ($info, $var, $method, $var_types) = @_;
    my $rtype = $var_types->{$var};
    if ($rtype) {
        for my $pp (keys %pkg_methods) {
            my $k = decl_key($pp, $method, $rtype);
            return $k if exists $decls{$k};
        }
    }
