    for my $d (values %decls) {
        next unless $d->{recv} && $d->{name} eq $method;
        push @scoped, $d->{key} if $imported_pp{$d->{pkgpath}} || pkgpath_from_rel($info->{file}) eq $d->{pkgpath};
    }
    return $scoped[0] if @scoped == 1;
    return undef;
}

for my $f (@all_go) {
    my $rel = rel($f);
