    my $clean = $info->{clean};

    pos($clean) = 0;
    while ($clean =~ /^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\([^)]*\)\s*(?:\([^)]*\)\s*)?\{/gm) {
        my ($recv_raw, $fname) = ($1, $2);
        my $start = pos($clean);
        my $recv = '';
        if (defined $recv_raw && $recv_raw ne '') {
            if ($recv_raw =~ /\*\s*([\w\.]+)/) { $recv = $1; }
            elsif ($recv_raw =~ /([\w\.]+)\s*$/) { $recv = $1; }
            $recv =~ s/^.*\.//;
        }
        my $rest = substr($clean, $start);
        my ($depth, $i, $len) = (1, 0, length($rest));
        while ($i < $len && $depth > 0) {
            my $c = substr($rest, $i, 1);
            if ($c eq '{') { $depth++ } elsif ($c eq '}') { $depth-- }
            $i++;
        }
        my $body = substr($rest, 0, $i);
        pos($clean) = $start + $i;
        my $var_types = infer_var_types($body);

        while ($body =~ /\b([\w\.]+)\.(\w+)\s*\(/g) {
            my ($lhs, $fn) = ($1, $2);
            next if $fn =~ /^(Bool|String|Int|Int64|Float64|Error|Bytes|Duration|Interface|Uint64)$/;
            if ($lhs =~ /^(\w+)$/) {
                my $key = resolve_func_call($info, $1, $fn);
                if ($key) { record_call($key, $info, $fname, $recv); next; }
                $key = resolve_method($info, $1, $fn, $var_types);
