    my @c = @{ $calls{$key} // [] };
    my (%callers, %files_c, %nt_callers, %nt_files);
    my $nt_sites = 0;
    for my $c (@c) {
        $callers{$c->{caller_id}} = 1;
        $files_c{$c->{caller_file}}++;
