}

sub is_test_file($) { $_[0] =~ /_test\.go$/ }
sub is_gen_file($) { $_[0] =~ /\.pb\.go$/ || $_[0] =~ /mock_/ }

sub strip_go_source($) {
    my ($s) = @_;
    $s =~ s/`(?:\\.|[^`\\])*`//gs;
    $s =~ s/"(?:\\.|[^"\\])*"//gs;
    $s =~ s/'(?:\\.|[^'\\])*'//gs;
    $s =~ s{//.*$}{}gm;
    $s =~ s{/\*.*?\*/}{}gs;
    return $s;
}

sub pkgpath_from_rel($) {
    my ($rel) = @_;
    return undef unless $rel =~ /^internal\//;
    my $dir = $rel;
    $dir =~ s{/[^/]+$}{};
    $dir =~ s{/}{.}g;
    return "$MOD/internal" if $dir eq 'internal';
    return "$MOD/$dir";
}

sub decl_key($$$) {
    my ($pkgpath, $name, $recv) = @_;
    $recv //= '';
    return "$pkgpath|$recv|$name";
}

sub parse_file($) {
    my ($file) = @_;
    open my $fh, '<', $file or return undef;
    local $/;
    my $src = <$fh>;
    close $fh;
    my $clean = strip_go_source($src);
    my $rel = rel($file);

    my ($pkg) = $clean =~ /^package\s+(\w+)/m;
    return undef unless defined $pkg;

    my %imports;
    while ($clean =~ /\bimport\s+(?:\(\s*(.*?)\s*\)|"([^"]+)"|(\w+)\s+"([^"]+)")/gs) {
        if (defined $2) {
            my $path = $2;
            (my $local = $path) =~ s/.*\///;
            $imports{$local} = $path;
        } elsif (defined $3) {
            $imports{$3} = $4;
        } elsif (defined $1) {
            my $block = $1;
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                $alias //= ($path =~ s/.*\///r);
                $imports{$alias} = $path;
            }
        }
    }

    my $pkgpath = pkgpath_from_rel($rel);
    my $full_pkgpath = "$MOD/" . $rel;
    $full_pkgpath =~ s{/[^/]+$}{};

    pos($clean) = 0;
