sub infer_var_types($) {
    my ($body) = @_;
    my %types;
    while ($body =~ /\b(\w+)\s*:?=\s*(?:&|\*)?([\w\.]+)\{/g) {
        my ($v, $t) = ($1, $2); $t =~ s/^.*\.//; $types{$v} = $t;
