sub pkgpath {
  my ($rel) = @_;
  return '' unless $rel =~ /^internal\//;
  my $dir = $rel; $dir =~ s{/[^/]+$}{};
  return "$MOD/internal" if $dir eq 'internal';
  return "$MOD/$dir";
}

sub strip {
  my ($s) = @_;
  $s =~ s/`(?:\\.|[^`\\])*`//gs;
  $s =~ s/"(?:\\.|[^"\\])*"//gs;
  $s =~ s/'(?:\\.|[^'\\])*'//gs;
  $s =~ s{//.*$}{}gm;
  $s =~ s{/\*.*?\*/}{}gs;
  return $s;
}

my @gos = split /\n/, `find '$ROOT' -name '*.go' 2>/dev/null`;
my %calls; # decl_key -> { sites, callers{}, files{}, nt_sites, nt_callers{}, nt_files{} }

sub bump {
  my ($k, $caller_id, $caller_file, $caller_test) = @_;
