open my $df,'<','/tmp/decls.tsv' or die;
while(<$df>){ chomp; my($pp,$rt,$name,$file,$ln,$sym)=split/\t/,$_,6;
  my $k = ($rt&&$rt ne '') ? "$pp|$rt|$name" : "$pp|$name";
  $decl{$k}={sym=>$sym,file=>$file,line=>$ln}; }

open my $if,'<','/tmp/imports.tsv' or die;
while(<$if>){ chomp; my($file,$alias,$path)=split/\t/; $imp{$file}{$alias}=$path; }

sub strip{ my($s)=@_; $s=~s/`(?:\\.|[^`\\])*`//gs; $s=~s/"(?:\\.|[^"\\])*"//gs;
  $s=~s/'(?:\\.|[^'\\])*'//gs; $s=~s{//.*$}{}gm; $s=~s{/\*.*?\*/}{}gs; $s }

sub pkgpath{ my($rel)=@_; return '' unless $rel=~/^internal\//; my $d=$rel; $d=~s{/[^/]+$}{};
  return "$MOD/internal" if $d eq 'internal'; return "$MOD/$d"; }

sub bump{ my($k,$cid,$cf,$ct)=@_; return unless $decl{$k};
  $calls{$k}{s}++; $calls{$k}{c}{$cid}=1; $calls{$k}{f}{$cf}=1;
  unless($ct){ $calls{$k}{nts}++; $calls{$k}{nc}{$cid}=1; $calls{$k}{nf}{$cf}=1; } }

for my $go (split/\n/,`find '$ROOT' -name '*.go'`){
  my $rel=$go; $rel=~s/^\Q$ROOT\E\/?//; open my $fh,'<',$go or next; local$/; my $src=<$fh>; close $fh;
  my $clean=strip($src); my $tst=($rel=~/ _test\.go$/ || $rel=~/ _test\.go/);
  $tst=($rel=~/ _test\.go$/); $tst=($rel=~/_test\.go$/);
  pos($clean)=0;
  while($clean=~/^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\([^)]*\)\s*(?:\([^)]*\)\s*)?\{/gm){
    my($rr,$fn)=($1,$2); my $start=pos($clean)-1; my $recv='';
    if(defined $rr&&$rr ne ''){ if($rr=~/\*\s*([\w\.]+)/){$recv=$1}elsif($rr=~/([\w\.]+)\s*$/){$recv=$1} $recv=~s/^.*\.//;}
    my $cid="$rel|$recv|$fn"; my $rest=substr($clean,$start); my($d,$i,$l)=(1,1,length($rest));
    while($i<$l&&$d>0){ my $c=substr($rest,$i,1); $d++ if $c eq '{'; $d-- if $c eq '}'; $i++; }
    my $body=substr($rest,0,$i);
    # qualified
    while($body=~/\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g){
      my($al,$fn2)=($1,$2); next if $fn2=~/^(Bool|String|Int|Int64|Float64|Error|Bytes|Duration|Interface|Uint64|Len|Less|Swap)$/;
      my $path=$imp{$rel}{$al}; next unless defined $path && index($path,"$MOD/internal")==0;
      my $k="$path|$fn2"; bump($k,$cid,$rel,$tst) if exists $decl{$k};
      # method on imported type named same as package? skip
    }
    # same package bare
    my $pp=pkgpath($rel); if($pp){
      while($body=~/(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/gm){
        my $fn2=$1; next if $fn2=~/^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|panic|recover|print|println)$/;
        my $k="$pp|$fn2"; bump($k,$cid,$rel,$tst) if exists $decl{$k};
      }
    }
  }
}
# debug GenUUID
my $gk="$MOD/internal/util|GenUUID";
print "GenUUID key exists: ", (exists $decl{$gk}? "yes":"no"), "\n";
print "GenUUID nts=", ($calls{$gk}{nts}//0), " total=", ($calls{$gk}{s}//0), "\n";

my @sorted=sort{($calls{$b}{nts}//0)<=>($calls{$a}{nts}//0)||($calls{$b}{s}//0)<=>($calls{$a}{s}//0)} keys %decl;
print "\nTOP 30 nt_sites:\n"; my $n=0;
for my $k(@sorted){ my $nt=$calls{$k}{nts}//0; next unless $nt>0; last if $n++>=30;
  my $d=$decl{$k}; printf "%s | %s:%d | nts=%d nc=%d nf=%d tot=%d\n",$d->{sym},$d->{file},$d->{line},$nt,
    scalar(keys%{$calls{$k}{nc}//{}}), scalar(keys%{$calls{$k}{nf}//{}}), $calls{$k}{s}//0; }
PERL

