ROOT=/bench/repo MOD=github.com/usememos/memos

# Fix import extraction with perl
perl -Mstrict -Mwarnings - "$ROOT" <<'PERL' > /tmp/imports.tsv
my ($ROOT) = @ARGV;
for my $go (split /\n/, `find '$ROOT' -name '*.go' 2>/dev/null`) {
  my $rel = $go; $rel =~ s/^\Q$ROOT\E\/?//;
  open my $fh, '<', $go or next;
  my @lines = <$fh>; close $fh;
  my $in = 0;
  for my $line (@lines) {
    if (!$in && $line =~ /^\s*import\s+\(\s*$/) { $in = 1; next; }
    if ($in) {
      if ($line =~ /^\s*\)\s*$/) { $in = 0; next; }
      if ($line =~ /^\s*(?:([A-Za-z0-9_]+)\s+)?"([^"]+)"/) {
        my ($alias, $path) = ($1, $2);
        if (!defined $alias) { ($alias = $path) =~ s|.*/||; }
        print "$rel\t$alias\t$path\n";
      }
      next;
    }
    if ($line =~ /^\s*import\s+(?:([A-Za-z0-9_]+)\s+)?"([^"]+)"/) {
      my ($alias, $path) = ($1, $2);
      if (!defined $alias) { ($alias = $path) =~ s|.*/||; }
      print "$rel\t$alias\t$path\n";
    }
  }
}
PERL

echo "imports=$(wc -l < /tmp/imports.tsv)"
grep "auth_service_session" /tmp/imports.tsv | grep util

# Rebuild decls if needed
pkgpath_from_rel() {
  local rel=$1; [[ $rel == internal/* ]] || return 1
  local dir; dir=$(dirname "$rel")
  if [[ $dir == internal ]]; then echo "$MOD/internal"; else echo "$MOD/$dir"; fi
}
> /tmp/decls.tsv
while IFS= read -r f; do
  rel=${f#$ROOT/}; pp=$(pkgpath_from_rel "$rel") || continue
  grep -n '^func ' "$f" | while IFS= read -r line; do
    ln=${line%%:*}; body=${line#*:}
    if echo "$body" | grep -q '^func ([^)]*) '; then
      recv=$(echo "$body" | sed -n 's/^func (\([^)]*\)).*/\1/p')
      name=$(echo "$body" | sed -n 's/^func ([^)]*) \+\([A-Za-z0-9_]*\).*/\1/p')
      rt=$(echo "$recv" | sed -E 's/.*\*?[[:space:]]*([A-Za-z0-9_.]+).*/\1/' | sed 's/.*\.//')
      echo -e "${pp}\t${rt}\t${name}\t${rel}\t${ln}\t(${rt}).${name}" >> /tmp/decls.tsv
    else
      name=$(echo "$body" | sed -n 's/^func \+\([A-Za-z0-9_]*\).*/\1/p')
      echo -e "${pp}\t\t${name}\t${rel}\t${ln}\t${name}" >> /tmp/decls.tsv
    fi
  done
done < <(find "$ROOT/internal" -name '*.go')

