    if(defined $rr&&$rr ne ''){ if($rr=~/\*\s*([\w\.]+)/){$recv=$1}elsif($rr=~/([\w\.]+)\s*$/){$recv=$1} $recv=~s/^.*\.//;}
    my $cid="$rel|$recv|$fn"; my $rest=substr($clean,$start); my($d,$i,$l)=(1,1,length($rest));
